<?php require_once __DIR__.'/../includes/auth.php'; require_role(['admin']); $pageTitle='Manage Categories'; require __DIR__.'/../includes/header.php'; $rows=$pdo->query('SELECT id,name,description,created_at FROM categories ORDER BY name')->fetchAll();echo '<h1>Manage categories</h1><div class="table-wrap"><table><tr><th>Category</th><th>Description</th><th>Created</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['description']).'</td><td>'.e($r['created_at']).'</td></tr>';}echo '</table></div>'; require __DIR__.'/../includes/footer.php'; ?>